UPDATE ai_runtime_publish_task
SET status = #{status}, updated_at_ms = #{nowMs}
WHERE tenant_id = #{tenantId} AND revision = #{revision}
  AND status IN ('PUBLISHED', 'PARTIAL', 'APPLIED', 'FAILED')
